811	static Tensor& add_relu_impl(
812	    Tensor& result, const Tensor& self, const Tensor& other, const Scalar& alpha) {
813	  auto iter = TensorIterator::binary_op(result, self, other);
814	  Scalar min_val;
815	  Scalar max_val;
816	  if (self.dtype() == at::kInt) {
817	    min_val = 0;
818	    max_val = std::numeric_limits<int32_t>::max();
819	  } else if (self.dtype() == at::kLong) {
820	    min_val = 0;
821	    max_val = std::numeric_limits<int64_t>::max();
822	  } else if (self.dtype() == at::kShort) {
823	    min_val = 0;
824	    max_val = std::numeric_limits<int16_t>::max();
825	  } else if (self.dtype() == at::kChar) {
826	    min_val = 0;
827	    max_val = std::numeric_limits<int8_t>::max();
828	  } else if (self.dtype() == at::kFloat) {
829	    min_val = 0.0;
830	    max_val = std::numeric_limits<float>::max();
831	  } else if (self.dtype() == at::kDouble) {
832	    min_val = 0.0;
833	    max_val = std::numeric_limits<double>::max();
834	  } else {
835	    TORCH_INTERNAL_ASSERT(
836	        false, "Unsupported datatype for add_relu:", self.dtype().name());
837	  }
838	
839	  result = iter.output();
840	  add_clamp_stub(iter.device_type(), iter, alpha, min_val, max_val);
841	  return result;
842	}
843	
844	Tensor& add_relu_out(const Tensor& self, const Tensor& other, const Scalar& alpha, Tensor& result) {
845	  return add_relu_impl(result, self, other, alpha);
846	}
